3081	/*
3082	 * This functions increases size of the main/expires db to match desired number.
3083	 * In cluster mode resizes all individual dictionaries for slots that this node owns.
3084	 *
3085	 * Based on the parameter `try_expand`, appropriate dict expand API is invoked.
3086	 * if try_expand is set to 1, `dictTryExpand` is used else `dictExpand`.
3087	 * The return code is either `DICT_OK`/`DICT_ERR` for both the API(s).
3088	 * `DICT_OK` response is for successful expansion. However ,`DICT_ERR` response signifies failure in allocation in
3089	 * `dictTryExpand` call and in case of `dictExpand` call it signifies no expansion was performed.
3090	 */
3091	static int dbExpandGeneric(kvstore *kvs, uint64_t db_size, int try_expand) {
3092	    int ret;
3093	    if (server.cluster_enabled) {
3094	        /* We don't know exact number of keys that would fall into each slot, but we can
3095	         * approximate it, assuming even distribution, divide it by the number of slots. */
3096	        int slots = getMyShardSlotCount();
3097	        if (slots == 0) return C_OK;
3098	        db_size = db_size / slots;
3099	        ret = kvstoreExpand(kvs, db_size, try_expand, dbExpandSkipSlot);
3100	    } else {
3101	        ret = kvstoreExpand(kvs, db_size, try_expand, NULL);
3102	    }
3103	
3104	    return ret? C_OK : C_ERR;
3105	}
3106	
3107	int dbExpand(redisDb *db, uint64_t db_size, int try_expand) {
3108	    return dbExpandGeneric(db->keys, db_size, try_expand);
3109	}
